// S3/S7 spike Worker (2026-10-24). Deployed once as `mailcellar-spike` with an R2 binding B
// (bucket mailcellar-spike) and a Workflow binding FLOW, then driven through the Cloudflare
// API: create instances with the params below, read CPU from Workers Observability.
// Mail here is synthetic test data generated by mime(); no real mailbox is read.
//   { op: 'seed', sizes: [5000, 50000], count: 40 }
//   { op: 'run', tag, size, count, perStep, steps, work: ['sha', 'gzip', 'put'], chain? }
//   { op: 'sub', steps: 3, n: 30, sleep? }
import { WorkflowEntrypoint } from 'cloudflare:workers';
const WORDS = 'the of and to in archive message report meeting invoice project update team schedule review account payment order shipping delivery'.split(' ');
function text(n, seed) { const parts = []; let len = 0, x = seed; while (len < n) { x = (x * 1103515245 + 12345) & 0x7fffffff; const w = WORDS[x % WORDS.length] + (x % 13 === 0 ? '.\r\n' : ' '); parts.push(w); len += w.length; } return parts.join('').slice(0, n); }
const b64e = (u8) => { let s = ''; for (let i = 0; i < u8.length; i += 32768) s += String.fromCharCode(...u8.subarray(i, i + 32768)); return btoa(s); };
function mime(size, i) {
  const small = Math.min(size, 20000);
  const att = size > 30000 ? b64e(new TextEncoder().encode(text(Math.floor((size - 20000) * 0.74), i + 3))).replace(/.{76}/g, '$&\r\n') : '';
  const b = 'b' + i;
  return ['From: "Sender ' + i + '" <sender' + (i % 50) + '@example.com>', 'To: test@example.com', 'Subject: Test message ' + i, 'Date: Mon, 1 Jan 2024 10:00:00 +0000', 'MIME-Version: 1.0', 'Content-Type: multipart/mixed; boundary="' + b + '"', '',
    '--' + b, 'Content-Type: text/plain; charset=utf-8', '', text(small * 0.4, i), '--' + b, 'Content-Type: text/html; charset=utf-8', '', '<html><body><p>' + text(small * 0.5, i + 7) + '</p></body></html>',
    ...(att ? ['--' + b, 'Content-Type: application/pdf; name="f.pdf"', 'Content-Transfer-Encoding: base64', '', att] : []), '--' + b + '--', ''].join('\r\n');
}
const b64urlDecode = (s) => { const bin = atob(s.replaceAll('-', '+').replaceAll('_', '/')); const a = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i); return a; };
async function gz(bytes) { return new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer()); }
function headerBlock(bytes) { const t = new TextDecoder().decode(bytes.subarray(0, Math.min(bytes.length, 65536))); return t.slice(0, t.indexOf('\r\n\r\n')); }
export class SpikeFlow extends WorkflowEntrypoint {
  async run(event, step) {
    const p = event.payload;
    if (p.op === 'seed') {
      for (const size of p.sizes) for (let i = 0; i < p.count; i++)
        await step.do('seed-' + size + '-' + i, async () => {
          const raw = new TextEncoder().encode(mime(size, i));
          const json = JSON.stringify({ id: (0x18c0000000 + i).toString(16), threadId: 't', labelIds: ['INBOX'], sizeEstimate: raw.length, internalDate: '1704103200000', raw: b64e(raw).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '') });
          await this.env.B.put('fx/' + size + '/' + i + '.json', json);
          return raw.length;
        });
      return 'seeded';
    }
    if (p.op === 'sub') {
      // Gmail-call cap: p.steps steps of p.n fetches each.
      const out = [];
      for (let k = 0; k < p.steps; k++) {
        if (p.sleep) await step.sleep('gap-' + k, p.sleep);
        out.push(await step.do('sub-' + k, { retries: { limit: 0, delay: 1000 } }, async () => {
          let ok = 0, err = null;
          try { for (let i = 0; i < p.n; i++) { const r = await fetch('https://www.cloudflare.com/cdn-cgi/trace?i=' + i); await r.text(); ok++; } } catch (e) { err = String(e).slice(0, 60); }
          return { ok, err };
        }));
      }
      return out;
    }
    if (p.op === 'run') {
      const out = [];
      for (let k = 0; k < p.steps; k++) {
        await step.sleep('gap-' + k, '1 second');
        out.push(await step.do('run-' + p.tag + '-' + k, { retries: { limit: 0, delay: 1000 } }, async () => {
          let bytes = 0, gzBytes = 0;
          for (let j = 0; j < p.perStep; j++) {
            const i = (k * p.perStep + j) % p.count;
            const obj = await this.env.B.get('fx/' + p.size + '/' + i + '.json');
            const m = JSON.parse(await obj.text());
            const raw = b64urlDecode(m.raw); bytes += raw.length;
            headerBlock(raw);
            if (p.work.includes('sha')) await crypto.subtle.digest('SHA-256', raw);
            let body = raw;
            if (p.work.includes('gzip')) { body = await gz(raw); gzBytes += body.length; }
            if (p.work.includes('put')) await this.env.B.put('out/' + p.tag + '/' + i + '.eml' + (body === raw ? '' : '.gz'), body);
          }
          console.log(JSON.stringify({ spike: p.tag, k, size: p.size, perStep: p.perStep, work: p.work.join('+'), bytes, gzBytes }));
          return { bytes, gzBytes };
        }));
      }
      if (p.chain > 0) await step.do('chain', async () => (await this.env.FLOW.create({ params: { ...p, chain: p.chain - 1, tag: p.tag.replace(/-c\d+$/, '') + '-c' + (p.chain - 1) } })).id);
      return out;
    }
  }
}
export default { fetch: () => new Response('spike', { status: 404 }) };
